import type { ActionDefinition } from '../../data/action_types'
import type { AnySchedule } from '../../data/action_schedule_types'
import type { Card } from '../../data/data_types'
import type { ClaudeRateLimitSnapshot } from '../../data/electron_claude_runtime_bridge'
import type { CodexRateLimitSnapshot } from '../../data/electron_codex_runtime_bridge'

export interface ActiveScheduleReference {
    available: boolean
    id: string
    label: string
    path: string | null
}

export interface ActiveScheduleTrackerReference {
    available: boolean
    label: string
}

export interface ActiveScheduleItem {
    actionAvailable: boolean
    actionLabel: string
    schedule: AnySchedule
    target: ActiveScheduleReference | null
    tracker: ActiveScheduleTrackerReference | null
    triggerCard: ActiveScheduleReference | null
    unavailableReasons: string[]
}

export interface ActiveScheduleProjectionSources {
    actions: ActionDefinition[]
    cards: Card[]
    claudeSnapshot: ClaudeRateLimitSnapshot | null
    codexSnapshot: CodexRateLimitSnapshot | null
}

function cardReference(cardInternalId: string, cards: Card[]): ActiveScheduleReference {
    const card = cards.find(({ header }) => header.internalId === cardInternalId)
    if (!card) return { available: false, id: cardInternalId, label: cardInternalId, path: null }

    return {
        available: true,
        id: cardInternalId,
        label: `${card.header.id} â€” ${card.header.title}`,
        path: card.path,
    }
}

function trackerReference(
    schedule: AnySchedule,
    claudeSnapshot: ClaudeRateLimitSnapshot | null,
    codexSnapshot: CodexRateLimitSnapshot | null,
): ActiveScheduleTrackerReference | null {
    if (schedule.trigger.type !== 'account-reset') return null
    const { agent, limitId, windowId } = schedule.trigger
    if (agent === 'claude') {
        const window = claudeSnapshot?.available && limitId === 'default'
            ? claudeSnapshot.windows.find(({ id }) => id === windowId)
            : null

        return { available: !!window, label: `Claude / ${limitId} / ${windowId}` }
    }
    if (agent === 'codex') {
        const bucket = codexSnapshot?.available
            ? codexSnapshot.buckets.find((candidate) => candidate.limitId === limitId)
            : null
        const window = windowId === 'primary' || windowId === 'secondary' ? bucket?.[windowId] : null
        const limitLabel = bucket?.limitName ?? limitId

        return { available: !!window, label: `Codex / ${limitLabel} / ${windowId}` }
    }

    return { available: false, label: `${agent} / ${limitId} / ${windowId}` }
}

/** Builds renderer-only labels and availability from backend-owned schedule records. */
export function projectActiveSchedules(
    schedules: readonly AnySchedule[],
    sources: ActiveScheduleProjectionSources,
): ActiveScheduleItem[] {
    const { actions, cards, claudeSnapshot, codexSnapshot } = sources

    return schedules.map((schedule) => {
        const action = actions.find(({ id }) => id === schedule.actionId)
        const targetCardInternalId = schedule.kind === 'action'
            ? schedule.context.cardInternalId ?? null
            : schedule.cardInternalIds[schedule.currentIndex]
        const target = targetCardInternalId ? cardReference(targetCardInternalId, cards) : null
        const triggerCard = schedule.trigger.type === 'card-state'
            ? cardReference(schedule.trigger.cardInternalId, cards)
            : null
        const tracker = trackerReference(schedule, claudeSnapshot, codexSnapshot)
        const unavailableReasons: string[] = []
        if (!action) unavailableReasons.push(`Action unavailable: ${schedule.actionId}`)
        if (target && !target.available) unavailableReasons.push(`Target card unavailable: ${target.id}`)
        if (triggerCard && !triggerCard.available) unavailableReasons.push(`Trigger card unavailable: ${triggerCard.id}`)
        if (tracker && !tracker.available) unavailableReasons.push(`Account tracker unavailable: ${tracker.label}`)

        return {
            actionAvailable: !!action,
            actionLabel: action?.label ?? schedule.actionId,
            schedule,
            target,
            tracker,
            triggerCard,
            unavailableReasons,
        }
    })
}

export type ActionScheduleTriggerType = 'account-reset' | 'at' | 'card-state'

interface ActionScheduleSnapshotBase {
    message: string | null
    open: boolean
    triggerType: ActionScheduleTriggerType
}

export interface AtActionScheduleSnapshot extends ActionScheduleSnapshotBase {
    timestamp: string
    triggerType: 'at'
}

export interface AccountResetActionScheduleSnapshot extends ActionScheduleSnapshotBase {
    agent: string
    limitId: string
    triggerType: 'account-reset'
    windowId: string
}

export interface CardStateActionScheduleSnapshot extends ActionScheduleSnapshotBase {
    cardInternalId: string
    targetState: string
    triggerType: 'card-state'
}

export type ActionScheduleSnapshot =
    | AccountResetActionScheduleSnapshot
    | AtActionScheduleSnapshot
    | CardStateActionScheduleSnapshot

export type ActionScheduleStoreSnapshot = ActionScheduleSnapshot & { anchorElement: HTMLElement | null }

interface AccountResetDraft {
    agent: string
    limitId: string
    windowId: string
}

interface CardStateDraft {
    cardInternalId: string
    targetState: string
}

const INITIAL_SNAPSHOT: ActionScheduleStoreSnapshot = {
    anchorElement: null,
    message: null,
    open: false,
    timestamp: '',
    triggerType: 'at',
}

/** Owns trigger-specific schedule form state at schedule-section boundary. */
export class ActionScheduleStore extends EventTarget {
    private readonly accountResetDraft: AccountResetDraft = { agent: '', limitId: '', windowId: '' }
    private readonly cardStateDraft: CardStateDraft = { cardInternalId: '', targetState: '' }
    private snapshot: ActionScheduleStoreSnapshot = INITIAL_SNAPSHOT
    private timestamp = ''

    readonly getSnapshot = () => this.snapshot
    readonly getOpenSnapshot = () => this.snapshot.open

    readonly subscribe = (listener: () => void) => {
        this.addEventListener('changed', listener)

        return () => this.removeEventListener('changed', listener)
    }

    toggle(anchorElement: HTMLElement) {
        if (this.snapshot.open) {
            this.close()
            return
        }

        this.publish({ ...this.snapshot, anchorElement, message: null, open: true })
    }

    close() {
        const { anchorElement, message, open } = this.snapshot
        if (!open && anchorElement === null && message === null) return

        this.publish({ ...this.snapshot, anchorElement: null, message: null, open: false })
    }

    setTriggerType(triggerType: ActionScheduleTriggerType) {
        if (triggerType === this.snapshot.triggerType) return

        const common = { anchorElement: this.snapshot.anchorElement, message: null, open: this.snapshot.open }
        if (triggerType === 'at') {
            this.publish({ ...common, timestamp: this.timestamp, triggerType })
            return
        }
        if (triggerType === 'account-reset') {
            this.publish({ ...common, ...this.accountResetDraft, triggerType })
            return
        }

        this.publish({ ...common, ...this.cardStateDraft, triggerType })
    }

    setTimestamp(timestamp: string) {
        this.timestamp = timestamp
        if (this.snapshot.triggerType === 'at') this.publish({ ...this.snapshot, message: null, timestamp })
    }

    setAgent(agent: string) {
        this.accountResetDraft.agent = agent
        this.accountResetDraft.limitId = ''
        this.accountResetDraft.windowId = ''
        if (this.snapshot.triggerType === 'account-reset') {
            this.publish({ ...this.snapshot, ...this.accountResetDraft, message: null })
        }
    }

    setAccountTracker(limitId: string, windowId: string) {
        this.accountResetDraft.limitId = limitId
        this.accountResetDraft.windowId = windowId
        if (this.snapshot.triggerType === 'account-reset') {
            this.publish({ ...this.snapshot, ...this.accountResetDraft, message: null })
        }
    }

    setCardInternalId(cardInternalId: string) {
        this.cardStateDraft.cardInternalId = cardInternalId
        if (this.snapshot.triggerType === 'card-state') {
            this.publish({ ...this.snapshot, cardInternalId, message: null })
        }
    }

    setTargetState(targetState: string) {
        this.cardStateDraft.targetState = targetState
        if (this.snapshot.triggerType === 'card-state') {
            this.publish({ ...this.snapshot, message: null, targetState })
        }
    }

    setMessage(message: string | null) {
        this.publish({ ...this.snapshot, message })
    }

    private publish(snapshot: ActionScheduleStoreSnapshot) {
        this.snapshot = snapshot
        this.dispatchEvent(new Event('changed'))
    }
}

